_sage_const_2000 = Integer(2000); _sage_const_60 = Integer(60); _sage_const_1024 = Integer(1024); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_16 = Integer(16); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_1 = Integer(1); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_0 = Integer(0); _sage_const_215040420000 = Integer(215040420000); _sage_const_167282265043404 = Integer(167282265043404); _sage_const_905 = Integer(905); _sage_const_964185327658080 = Integer(964185327658080); _sage_const_6071 = Integer(6071); _sage_const_612218384750 = Integer(612218384750); _sage_const_9525021973931919 = Integer(9525021973931919); _sage_const_18100 = Integer(18100); _sage_const_29561828382772029 = Integer(29561828382772029); _sage_const_65380 = Integer(65380); _sage_const_50 = Integer(50); _sage_const_40 = Integer(40); _sage_const_20 = Integer(20); _sage_const_30 = Integer(30); _sage_const_25 = Integer(25); _sage_const_35 = Integer(35)
import mpmath
mpmath.mp.dps = _sage_const_2000

# ============================================================
# Step 1: Compute P2.7 sequences in exact arithmetic
# ============================================================
N = _sage_const_60

def A_p27(n):
    return QQ(_sage_const_1024 ) * (_sage_const_2 *n+_sage_const_5 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 )

def B_p27(n):
    return QQ(_sage_const_128 ) * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_104060 *n**_sage_const_6  + _sage_const_1745370 *n**_sage_const_5  +
        _sage_const_12145238 *n**_sage_const_4  + _sage_const_44886481 *n**_sage_const_3  + _sage_const_92943995 *n**_sage_const_2  + _sage_const_102256019 *n + _sage_const_46709052 )

def C_p27(n):
    return QQ(_sage_const_16 ) * (n+_sage_const_3 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_3784 *n**_sage_const_5  + _sage_const_57792 *n**_sage_const_4  +
        _sage_const_351019 *n**_sage_const_3  + _sage_const_1059230 *n**_sage_const_2  + _sage_const_1587211 *n + _sage_const_944620 )

def D_p27(n):
    return QQ(_sage_const_1 ) * (n+_sage_const_3 )**_sage_const_4  * (n+_sage_const_4 )**_sage_const_6  * (_sage_const_946 *n**_sage_const_2  + _sage_const_4515 *n + _sage_const_5399 )

q = [QQ(_sage_const_0 )] * N
q[_sage_const_0 ] = QQ(-_sage_const_215040420000 )
q[_sage_const_1 ] = QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 )
q[_sage_const_2 ] = QQ(-_sage_const_964185327658080 ) / QQ(_sage_const_6071 )

for n in range(_sage_const_2 , N-_sage_const_1 ):
    q[n+_sage_const_1 ] = (B_p27(n) * q[n] - C_p27(n-_sage_const_1 ) * q[n-_sage_const_1 ] + D_p27(n-_sage_const_2 ) * q[n-_sage_const_2 ]) / A_p27(n)

p = [QQ(_sage_const_0 )] * N
p[_sage_const_0 ] = QQ(-_sage_const_612218384750 )
p[_sage_const_1 ] = QQ(-_sage_const_9525021973931919 ) / QQ(_sage_const_18100 )
p[_sage_const_2 ] = QQ(-_sage_const_29561828382772029 ) / QQ(_sage_const_65380 )

for n in range(_sage_const_2 , N-_sage_const_1 ):
    p[n+_sage_const_1 ] = (B_p27(n) * p[n] - C_p27(n-_sage_const_1 ) * p[n-_sage_const_1 ] + D_p27(n-_sage_const_2 ) * p[n-_sage_const_2 ]) / A_p27(n)

# ============================================================
# Step 2: Compute L = ζ(2)+ζ(3) at 2000 digits
# ============================================================
L = mpmath.zeta(_sage_const_2 ) + mpmath.zeta(_sage_const_3 )
print("L = ζ(2)+ζ(3) (first 50 digits):")
print("  %s" % mpmath.nstr(L, _sage_const_50 ))

# ============================================================
# Step 3: Compute p/q - L at ultra-high precision
# ============================================================
print("\n=== p_n/q_n - L at 2000-digit precision ===")
for n in range(min(_sage_const_40 , N)):
    if q[n] != _sage_const_0 :
        # Convert to mpmath for high precision
        p_mp = mpmath.mpf(p[n].numerator()) / mpmath.mpf(p[n].denominator())
        q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())

        ratio = p_mp / q_mp
        diff = ratio - L
        if n <= _sage_const_20 :
            print("n=%2d: p/q - L = %s" % (n, mpmath.nstr(diff, _sage_const_30 )))

# ============================================================
# Step 4: Compute e_n = p_n - L·q_n and e_n/q_n
# ============================================================
print("\n=== e_n = p_n - L·q_n ===")
e_vals = []
for n in range(min(_sage_const_40 , N)):
    p_mp = mpmath.mpf(p[n].numerator()) / mpmath.mpf(p[n].denominator())
    q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())
    e = p_mp - L * q_mp
    e_vals.append(e)
    if n <= _sage_const_20 :
        print("n=%2d: e = %s, e/q = %s" % (n, mpmath.nstr(e, _sage_const_25 ), mpmath.nstr(e/q_mp, _sage_const_25 ) if q_mp != _sage_const_0  else "?"))

# ============================================================
# Step 5: Error decay rate
# ============================================================
print("\n=== e_{n+1}/e_n ===")
for n in range(min(_sage_const_35 , len(e_vals)-_sage_const_1 )):
    if abs(e_vals[n]) > _sage_const_0 :
        ratio = e_vals[n+_sage_const_1 ] / e_vals[n]
        print("n=%2d: %s" % (n, mpmath.nstr(ratio, _sage_const_20 )))

# ============================================================
# Step 6: q_{n+1}/q_n (Poincaré)
# ============================================================
print("\n=== q_{n+1}/q_n ===")
for n in range(min(_sage_const_35 , N-_sage_const_1 )):
    if q[n] != _sage_const_0 :
        r = float(q[n+_sage_const_1 ]/q[n])
        print("n=%2d: %.15f" % (n, r))

# ============================================================
# Step 7: Check absolute value pattern of e/q
