print("\n=== |e_n/q_n| pattern ===")
for n in range(min(_sage_const_35 , len(e_vals))):
    if q[n] != _sage_const_0 :
        q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())
        ratio = abs(e_vals[n] / q_mp)
        print("n=%2d: |e/q| = %s" % (n, mpmath.nstr(ratio, _sage_const_20 )))
